package in.asr.ambulance;
import org.json.*;
public final class CompletionQueueTest {
  static int count;static void yes(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
  static JSONObject object(Object... values)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<values.length;i+=2)o.put((String)values[i],values[i+1]);return o;}
  static final class Memory implements ActionQueue.Store{JSONObject state=new JSONObject();public JSONObject read(){return new JSONObject(state.toString());}public void write(JSONObject next){state=new JSONObject(next.toString());}}
  public static void main(String[] args)throws Exception{
    long now=1000000;JSONObject proof=object("activity_code","completed","completion_note","Receiving team accepted handover.","photo_base64","private-JPEG-test-marker","photo_captured_at",now-10000,"latitude",18.329,"longitude",82.877,"recorded_at",now-5000,"accuracy_m",12,"mock_location",false,"_session_tag","session-A");
    yes(CompletionEvidence.valid(proof,now),"fresh evidence valid");JSONObject stale=new JSONObject(proof.toString()).put("photo_captured_at",now-120001);yes(!CompletionEvidence.valid(stale,now),"expiredphoto rejected");yes(!CompletionEvidence.valid(new JSONObject(proof.toString()).put("mock_location",true),now),"mockfix rejected");yes(!CompletionEvidence.valid(new JSONObject(proof.toString()).put("completion_note",""),now),"note required");yes(!CompletionEvidence.valid(new JSONObject(proof.toString()).put("recorded_at",now+1),now),"futurefix rejected");yes(CompletionEvidence.sameSession(proof,"session-A"),"same session proof allowed");yes(!CompletionEvidence.sameSession(proof,"session-B"),"newsession cannot replayoldproof");yes(!CompletionEvidence.sameSession(new JSONObject(),"session-A"),"missingbinding rejects legacycompletion");
    String unicode=new String(new char[700]).replace('\0','\u0C05');yes(!CompletionEvidence.valid(new JSONObject(proof.toString()).put("completion_note",unicode),now),"UTF-8 note matches server byte bound");
    Memory memory=new Memory();ActionQueue queue=new ActionQueue(memory);String id=queue.add("https://mapa.test","company|crew|driver","ambulance-A","order_A",proof,now);String exact=memory.state.getJSONArray("actions").getJSONObject(0).getJSONObject("body").toString();
    queue.drain("https://mapa.test","company|crew|driver","ambulance-A",now,payload->{throw new java.io.IOException("uncertain timeout");});yes(memory.state.getJSONArray("actions").length()==1,"uncertain response keeps photo");JSONObject saved=memory.state.getJSONArray("actions").getJSONObject(0);yes(id.equals(saved.getJSONObject("body").getString("action_id")),"same id saved");yes(exact.equals(saved.getJSONObject("body").toString()),"uncertain body immutable");
    final int[] sends={0};queue.drain("https://other.test","company|crew|driver","ambulance-A",now+100000,payload->{sends[0]++;return object("ok",true);});yes(sends[0]==0,"origin cannot adopt evidence");queue.drain("https://mapa.test","othercrew","ambulance-A",now+100000,payload->{sends[0]++;return object("ok",true);});yes(sends[0]==0,"owner cannot adopt evidence");
    queue.retry("https://mapa.test","company|crew|driver");queue.drain("https://mapa.test","company|crew|driver","ambulance-A",now+130000,payload->{yes(exact.equals(payload.toString()),"later retry exactphoto/body even expired");return object("ok",true,"replayed",true);});yes(memory.state.getJSONArray("actions").length()==0,"confirmedlate receipt deletes pendingphoto");
    String rejected=queue.add("https://mapa.test","company|crew|driver","ambulance-A","order_A",proof,now);queue.drain("https://mapa.test","company|crew|driver","ambulance-A",now,payload->{throw new ActionQueue.Problem(422,"Retake fresh completion evidence");});JSONObject blocked=memory.state.getJSONArray("actions").getJSONObject(0);yes("blocked".equals(blocked.getString("state")),"definiterejection quarantined");yes(blocked.getInt("rejection_status")==422,"status exposes recapture option");yes(blocked.getJSONObject("body").optString("photo_base64").equals(proof.getString("photo_base64")),"blockedphoto retaineduntilrecapture/discard");queue.discard("https://mapa.test","othercrew",rejected);yes(memory.state.getJSONArray("actions").length()==1,"othercrew cannot discard evidence");queue.discard("https://mapa.test","company|crew|driver",rejected);yes(memory.state.getJSONArray("actions").length()==0,"owner explicitly recaptures after definitefailure");
    System.out.println("Trip-end evidence / queue behavior assertions: "+count);
  }
}
